import { Router } from "express";
import { CreditMoney, DepositMoney, SendMoney } from "./transaction.controller.js";
import { authenticate } from "../../shared/middleware/Authentication.js";
import { authorizeTransactionAccess } from "../../shared/middleware/Authorization.js";
import { idempotencyMiddleware } from "../../shared/middleware/Idempotency.js";
const router = Router();
router.use(authenticate);
router.post("/send/:senderAccountNo/:receiverAccountNo", authorizeTransactionAccess("senderAccountNo", "accountNo"), idempotencyMiddleware, SendMoney);
router.post("/deposit", authorizeTransactionAccess("sender_account_id", "accountId"), idempotencyMiddleware, DepositMoney);
router.post("/withdraw/:accountNo", authorizeTransactionAccess("accountNo", "accountNo"), idempotencyMiddleware, CreditMoney);
export const transactionRoutes = router;
